mapper.select:


    inner join sys_user u on u.user_name = tcheckhistory.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tcheckhistory.del_flag = '0'
     and tcheckhistory.task_detail_id = #{taskDetailId}
     and tcheckhistory.stock_id = #{stockId}
     and tcheckhistory.predict_count = #{predictCount}
     and tcheckhistory.actual_count = #{actualCount}
     and tcheckhistory.material_id = #{materialId}
     and tcheckhistory.batch_number = #{batchNumber}
     and tcheckhistory.material_code like concat('%', #{materialCode}, '%')
     and tcheckhistory.tray_id = #{trayId}


${params.dataScope}
